        intel2 = "WAEC Paper 1 tests distinguishing 'since' (exact starting point: since 2019 / since morning) vs 'for' (duration span: for five years / for two hours!).",
        recap1 = "Finished time word (yesterday/ago/last year) → Simple Past V₂! 'Since/So far/Yet' → Present Perfect!",
        recap2 = "Broadcast, Forecast, Burst, Cast, Cost, Cut, Put, Spread → ZERO '-ed'!",
        sec3Title = "3. Tricky Irregular V₃ Participles, Since/For & Mixed Conditionals",
        sec3Body = "Memorize exam-favourite irregular V₁/V₂/V₃ sets: Swim-Swam-Swum, Drink-Drank-Drunk, Ring-Rang-Rung, Bear-Bore-Borne (carry/give birth: 'borne fruit'; vs 'born' strictly passive birth!), Wind-Wound-Wound, Grind-Ground-Ground (never 'grinded'!). Compare 'Have been to' (visited and returned) vs 'Have gone to' (still there right now!).",
        sec3Formula = "\\text{Type 3: } \\text{If } + \\text{had } V_3 \\;\\longrightarrow\\; \\text{would/could have } V_3   |   \\text{Type 2: } \\text{If } + V_2/\\text{were} \\;\\longrightarrow\\; \\text{would } V_1",
        sec3Tip = "'Since' marks a POINT in time (since Tuesday); 'For' marks a LENGTH of time (for 3 days)!",
        sec3Mech = "Past Perfect 'had + V₃' pairs cleanly with a later Simple Past verb ('By the time the teacher arrived, the students HAD WRITTEN the test').",
        sec3Intel = "NECO/JAMB frequently test 'The thief was ___' → 'HANGED' (executed) vs 'The portrait was HUNG'!",
        sec3Recap = "Zero '-ed' on Broadcast/Forecast/Split/Burst/Cost; Execute = Hanged!",
        sec4Title = "4. Reporting Broadcast News & CV/Application Timing",
        sec4Body = "When Nigerian radio anchors say 'NTA broadcasted live yesterday', they fall into the '-ed' error—standard form is 'NTA broadcast live'! Similarly, saying 'I am living in Abuja since 2018' drops Present Perfect Continuous ('I have been living in Abuja since 2018').",
        sec4Tip = "Never say 'I am working here since 2020'—use 'I HAVE BEEN working here since 2020'!",
        sec5Title = "5. Conditional Tense Symmetry Audit",
        sec5Body = "Never put 'would' inside the 'IF' clause ('If I would have seen him...' is wrong!). Keep 'will/would' STRICTLY in the main result clause, and align Type 1 (V₁ + will), Type 2 (V₂/were + would V₁), Type 3 (had V₃ + would have V₃) cleanly!",
        sec5Tip = "By the time + Simple Past → Main verb takes Future/Past Perfect ('will have + V₃' / 'had + V₃')!",
        misc1 = MisconceptionAnalysis("Adding '-ed' to 'broadcast', 'forecast', or 'grind' gives valid past tense ('broadcasted', 'grinded').", "Regular verb pattern.", "Broadcast, Forecast, Burst, Cast, Cost, Split stay UNCHANGED (V₁=V₂=V₃); Grind changes to GROUND!", "Check irregular invariant verbs before adding -ed."),
        misc2 = MisconceptionAnalysis("'Since' can be used with durations like 'since three hours'.", "Informal speech mixup.", "'For' measures duration ('for three hours / for five years'); 'Since' anchors exact starting point ('since 2 o'clock / since 2021')!", "Point = Since; Span = For."),
        guidedPrompt = "Fix all verb tense and conditional errors in: 'Had I knew earlier, I would report to the station; NTA already broadcasted the news since three hours ago.'",
        guidedHints = listOf(
          "Hint 1: Type 3 inversion requires Past Participle V₃ ('Had I KNOWN') + 'would HAVE REPORTED'.",
          "Hint 2: 'Broadcast' has no '-ed' form → 'had already broadcast'.",
          "Hint 3: Duration uses 'FOR three hours' (or 'three hours ago' without 'since'!).",
        ),
        guidedApproach = "Align Type 3 (Had V₃ + would have V₃) → fix invariant broadcast → choose For vs Ago.",
        guidedSolution = "'Had I known earlier, I would have reported to the station; NTA had already broadcast the news three hours earlier (or has been broadcasting for three hours).'",
        projTitle = "Broadcast Desk Tense & Conditional Style Guide",
        projScenario = "Audit 4 draft radio news scripts correcting invariant irregular verbs, since/for errors, and Type 2/3 conditional slips.",
        projStages = listOf("Fix 'forecasted / splitted' → 'forecast / split'.", "Replace 'since two weeks' with 'for two weeks'.", "Align 'If the governor came... will sign' → 'would sign' (or Type 1 'comes... will sign')."),
        projRubric = listOf("Catches all non-standard '-ed' verbs.", "Enforces Since(point) vs For(span).", "Matches Conditional Type 2 & 3 pairs."),
        projModel = "'Metereologists forecast heavy rain yesterday; if residents had cleared drains earlier, floods would not have submerged roads, as teams have been pumping water for two weeks.'",
        cheatOverview = "Ago/Yesterday=V₂; Since=Present Perfect; Type 2(were+would); Type 3(had V₃+would have V₃).",
        cheatLegend = listOf("Broadcast=Broadcast", "Hanged=Executed", "For=Duration", "Since=Start point"),
        cheatTraps = listOf("Using 'broadcasted/costed'", "Writing 'would' inside If-clause", "Matching Present Perfect with 'yesterday'"),
        cheatMemory = "Had I KNOWN + Would Have V₃; Point = Since, Period = For!",
      ),
      "eng_05_subjunctive_passive" to spec(
        prereq = listOf("eng_04_tenses_conditionals"),
        dep = "Mandative subjunctives, causative verbs, and tense backshifting control Concord, Question Tags, and Formal Reporting.",
        vocab = listOf(
          VocabularyEntry("It is (high) time...", "Idiomatic unreal past structure demanding Simple Past V₂ for an overdue present action.", "Complaining something should ALREADY be done right now!", "'It is high time we LEFT' (NOT 'leave' or 'should leave'!)."),
          VocabularyEntry("Mandative Subjunctive", "Bare root verb V₁ (no '-s', use 'be') after suggest, insist, demand, recommend + that.", "Formal committee rule locking bare infinitive regardless of singular subject!", "'The panel recommended that she SUBMIT [not submits] the report'!"),
          VocabularyEntry("Causative (Make/Let/Have)", "'Make/Let/Help + person + bare V₁'; 'Have/Get + thing + V₃'!", "Ordering someone vs having a service done to your object.", "'He made me DO it' (no 'to'!); 'I had my phone REPAIRED' (V₃)!"),
          VocabularyEntry("Reported Speech Backshift", "Present → Past; Past → Past Perfect; Will → Would; Here → There; Today → That day.", "Stepping verb tense one rung backward when reporting past speech.", "Universal truths keep present tense ('Teacher said the Earth REVOLVES')!"),
        ),
        mech1 = "Why does 'I wish I WERE taller' and 'It is high time we WENT home' look like Past Tense when talking about TODAY? Because English uses Past Tense distance to signal HYPOTHETICAL / OVERDUE / UNREAL wishes in the present ('I wish I had a car NOW'; use 'had + V₃' ONLY for past regrets like 'I wish I had studied yesterday')!",
        mech2 = "In Passive Voice, the verb 'TO BE' carries the exact original tense followed strictly by Past Participle V₃: Continuous Active ('is repairing') → Passive ('is BEING repaired'); Perfect ('has repaired') → Passive ('has BEEN repaired')!",
        intel1 = "JAMB tests 'It is high time + V₂', 'would rather + subject + V₂' (vs 'would rather + bare V₁' without second subject!), 'made him confess' (no 'to' in active!), and 'used to' vs 'BE used to + -ing'!",
        intel2 = "WAEC Paper 1 tests converting direct questions into embedded statements (removing do/did and swapping subject BEFORE verb: 'He asked where I LIVED', NOT 'where did I live'!).",
        recap1 = "It is high time + subject + SIMPLE PAST V₂; Mandative (suggest/demand that) + BARE V₁!",
        recap2 = "Active 'made him cry' (no 'to') flips in Passive to 'was made TO cry' (restores 'to'!).",
        sec3Title = "3. 'Used To' vs 'Be Used To', Causatives & Embedded Questions",
        sec3Body = "Contrast two look-alikes carefully: (1) 'USED TO + bare V₁' = past habit now stopped ('We used to walk to school'); (2) 'AM/IS/ARE/GET USED TO + -ING noun/gerund' = accustomed to something ('She is used to WAKING up early'—here 'to' is a preposition!). Same rule applies to 'look forward to + -ING', 'with a view to + -ING', and 'object to + -ING'!",
        sec3Formula = "\\text{It is high time + Subj + } V_2   |   \\text{Be used to / Look forward to + } V\\text{-ing}",
        sec3Tip = "'Would rather' shifts rules instantly if a SECOND person appears: 'I would rather GO home' (bare V₁), BUT 'I would rather YOU WENT home' (V₂ Past!)!",
        sec3Mech = "Because introducing a second subject makes you wish someone else acted, English switches right into unreal Subjunctive Past V₂.",
        sec3Intel = "JAMB tests 'look forward to SEEING you' and 'used to WAKING' relentlessly against bare infinitive traps.",
        sec3Recap = "Look forward to / Accustomed to / Used to (with be/get) → ALL take -ING!",
        sec4Title = "4. Formal Boardroom Minutes & Reporting Eyewitness News",
        sec4Body = "Company secretaries draft formal resolutions strictly in Mandative Subjunctive ('The board moved that the auditor BE appointed immediately'), while journalists keep reported questions smoothly embedded ('The commissioner asked when the bridge would open', never question word-order!).",
        sec4Tip = "Indirect questions NEVER keep question marks or 'did/do' inversion!",
        sec5Title = "5. Passive 'Made To' & Backshift Exception Audit",
        sec5Body = "Remember two symmetrical traps: (1) Active 'The coach made us RUN' drops 'to', whereas Passive 'We were made TO RUN' puts 'to' back in! (2) Reported general science laws ('She said water BOILS at 100°C') refuse past backshift because nature stays true today.",
        sec5Tip = "'Suggest' NEVER takes object + infinitive ('He suggested me to go' is WRONG! Use 'He suggested THAT I GO / going')!",
        misc1 = MisconceptionAnalysis("'I look forward to hear from you soon' is correct formal letter closing.", "'to' always takes bare verb V₁.", "In 'look forward to', 'object to', 'with a view to', and 'be used to', 'to' is a PREPOSITION—demanding -ING gerund ('hearing')!", "Prepositional 'to' expressions take -ING!"),
        misc2 = MisconceptionAnalysis("'It is high time we go' is right because we are leaving now.", "Present urgency.", "'It is (high/about) time + subject' requires UNREAL SIMPLE PAST V₂ ('we WENT')!", "High time + Subject → Past Tense V₂."),
        guidedPrompt = "Choose the right forms and explain why: (a) 'It is high time the committee ___ (submits / submitted) its findings.' (b) 'The committee insisted that the treasurer ___ (resigns / resign).' (c) 'Ada is used to ___ (wake / waking) at 5 a.m.'",
        guidedHints = listOf(
          "Hint 1: (a) 'It is high time + subject' triggers unreal Simple Past V₂ → 'submitted'.",
          "Hint 2: (b) 'insisted that' triggers Mandative Subjunctive bare V₁ → 'resign' (NO '-s'!).",
          "Hint 3: (c) 'is used to' expresses present custom ('accustomed to') → requires -ING gerund 'waking'!",
        ),
        guidedApproach = "Contrast High-Time V₂ vs Mandative bare V₁ vs Prepositional 'is used to + -ing'.",
        guidedSolution = "(a) 'submitted' (High time takes Past V₂). (b) 'resign' (Mandative subjunctive drops third-person '-s'). (c) 'waking' ('is used to' uses preposition 'to' + gerund).",
        projTitle = "Executive Board Minutes & Press Reporting Conversion",
        projScenario = "Convert 3 direct executive remarks into error-free formal board minutes preserving subjunctive and reported backshifts.",
        projStages = listOf("Convert direct question 'Where did you store the vaccines?' into reported speech.", "Keep Mandative Subjunctive inside 'We recommend that he...' clause.", "Fix 'I wish I am...' → 'were'."),
        projRubric = listOf("Drops 'did' and restores S+V order.", "Uses bare V₁ inside recommend-that.", "Uses 'were' for present wish."),
        projModel = "1) 'The chair asked where they had stored the vaccines.' 2) 'The board recommended that the accountant submit daily ledgers.' 3) 'The director wished the generator were quieter.'",
        cheatOverview = "High time+V₂; Suggest/Insist that+Bare V₁; Look forward to+-ing; Wish(now)+V₂/were.",
        cheatLegend = listOf("Be used to + -ing", "Used to + V₁", "Make sb do / Was made TO do", "Suggest + that / -ing"),
        cheatTraps = listOf("Writing 'look forward to see'", "Adding '-s' inside Mandative that-clause", "Keeping 'did' inside reported questions"),
        cheatMemory = "High Time = V₂ Past; Suggest That = Bare Stem; Be Used To = -ING!",
      ),
      "eng_06_concord" to spec(
        prereq = listOf("eng_01_parts_affixes (countable/uncountable nouns)"),
        dep = "Subject-verb concord governs error-free Essay Expression, Question Tags, and Formal Comprehension answers.",
        vocab = listOf(
          VocabularyEntry("Parenthetical Bypass", "Ignoring intervening commas ('as well as, along with, together with, including, accompanied by').", "Crossing out side-passengers to match ONLY the main driver!", "'The principal, along with 20 teachers, IS [not are] attending'!"),
          VocabularyEntry("Proximity Concord", "Verb matches CLOSER subject after 'Neither... nor / Either... or / Not only... but also'.", "Nearest-neighbor verb handshake.", "'Neither the students nor the TEACHER WAS ready'; flip subjects → 'WERE'!"),
          VocabularyEntry("Double-Title vs Two People", "'The accountant and treasurer IS...' (ONE person—one 'THE') vs 'The accountant and THE treasurer ARE...' (TWO people!).", "Count 'THE' determiners to count real heads!", "'Bread and butter IS my breakfast' (1 dish) vs 'Time and tide WAIT'."),
          VocabularyEntry("Indefinite Singular Pronouns", "Each, Every, Everyone, Everybody, Someone, Anyone, Nobody, Neither, Either, Many a.", "ALWAYS SINGULAR verbs despite plural-sounding groups!", "'Everyone HAS submitted'; 'Neither of the boys KNOWS'; 'Many a student FAILS'!"),
        ),
        mech1 = "Why does 'One of the students who STUDY hard IS winning' use PLURAL 'study' while main verb 'IS' stays singular? Look closely at each clause's true subject: WHO sits right behind plural 'students' (so those students study!), whereas the main sentence subject is ONE (just one student is winning!)! Watch out for 'ONLY one of the students who STUDIES' where 'only' pins focus on single!",
        mech2 = "Measurements of money, distance, time, or weight act as ONE SINGLE lump sum and take SINGULAR verbs ('Ten million naira IS huge'; 'Fifty kilometres IS a long drive'), whereas 'A number of students ARE absent' (many students!) contrasts cleanly with 'THE number of students IS fifty' (a single count figure!).",
        intel1 = "JAMB tests 'The + adjective' plural human groups ('The POOR ARE...', 'The elderly NEED...'), 'A number of' vs 'The number of', and 'Many a + singular noun + singular verb'!",
        intel2 = "WAEC Paper 1/2 marks down essay scores sharply when candidates match verbs to the nearest plural word inside a prepositional phrase ('The quality of these bags ARE good' → WRONG! 'quality IS'!).",
        recap1 = "Find the TRUE head noun BEFORE 'of / with / along with'—never let trailing plurals hijack the verb!",
        recap2 = "A number of = Plural ('are'); The number of = Singular ('is').",
        sec3Title = "3. Collective Nouns, Fractions & 'More Than One' Rules",
        sec3Body = "Collective nouns (committee, jury, team, audience, police, cattle): 'Police' and 'Cattle' and 'Youths' ALWAYS take PLURAL ('The police ARE investigating'—never 'police is'!). Team/Committee take SINGULAR when acting as one body ('The team IS united') and PLURAL when acting individually ('The team ARE arguing'). Fractions match the noun AFTER 'of' ('Half of the cake IS gone' vs 'Half of the cakes ARE gone')!",
        sec3Formula = "\\text{A number of + Plural + PLURAL V}   |   \\text{The number of + Plural + SINGULAR V}   |   \\text{Police / Cattle + ARE}",
        sec3Tip = "Always count words cleanly: 'More than one student HAS passed' (SINGULAR!), whereas 'More students than one HAVE passed' (PLURAL!)!",
        sec3Mech = "'More than one' pairs directly with singular noun 'student', triggering singular verb agreement.",
        sec3Intel = "NECO/JAMB love pairing 'More than one + sing.' and 'Many a + sing.' specifically because they sound plural yet demand SINGULAR verbs!",
        sec3Recap = "Police/Cattle/The poor = ALWAYS Plural; Many a / More than one / Everything = ALWAYS Singular.",
        sec4Title = "4. Fixing Concord Errors in Nigerian News & School Prefects",
        sec4Body = "Headline writers frequently err with 'The police has arrested...', 'A number of lecturers has resigned', or 'One of the candidates were disqualified'. Mastering parenthetical bypass + head-noun extraction turns candidates into precision editors.",
        sec4Tip = "'The poor / The rich / The unemployed' mean ALL such people → ALWAYS PLURAL verb!",
        sec5Title = "5. Prepositional-Object & Relative-Clause Concord Audit",
        sec5Body = "Cross out every 'of ___ / with ___ / in ___' phrase mentally before picking IS vs ARE: 'The cost [of building three schools] WAS high!' Only for fractions/percentages ('60% of the water IS' vs '60% of the books ARE') do you peek inside the 'of'-phrase!",
        sec5Tip = "Never let 'with / together with / as well as' turn a singular subject plural!",
        misc1 = MisconceptionAnalysis("'A number of students' and 'The number of students' both take singular verbs because 'number' is singular.", "Both start with 'number'.", "'A number of' is an idiom meaning 'several/many' → PLURAL verb ('A number of students WERE late'); 'The number of' means the specific count figure → SINGULAR verb ('The number of students IS 40')!", "A number = Many (ARE); The number = One figure (IS)."),
        misc2 = MisconceptionAnalysis("'Neither Ada nor her friends was invited' is right because 'Neither' is singular.", "Solo 'Neither of...' is singular.", "With 'Neither... NOR / Either... OR', verb obeys PROXIMITY to the nearer noun—plural 'friends' forces 'WERE'!", "Neither alone = Singular; Neither...nor = Match nearer subject!"),
        guidedPrompt = "Select the correct verb and justify each: (a) 'The Principal, as well as the teachers, ___ (is/are) attending.' (b) 'Neither the teachers nor the Principal ___ (was/were) briefed.' (c) 'A number of cows and cattle ___ (is/are) grazing, while the number of goats ___ (is/are) six.'",
        guidedHints = listOf(
          "Hint 1: (a) Cross out ', as well as the teachers,' → singular 'The Principal' → 'is'.",
          "Hint 2: (b) Proximity to 'nor' looks at closer 'the Principal' → 'was'.",
          "Hint 3: (c) 'A number of' + 'cattle' = Plural ('are'); 'The number of' = Single figure ('is').",
        ),
        guidedApproach = "Parenthetical bypass → Proximity rule → A-number vs The-number + Cattle always plural.",
        guidedSolution = "(a) 'is' (ignore parenthetical 'as well as...'). (b) 'was' (proximity agrees with closer singular 'Principal'). (c) 'are' ('A number of' + cattle plural), then 'is' ('The number of' is one figure).",
        projTitle = "Newsroom Headline Concord Proofreading Test",
        projScenario = "Audit 4 draft campus bulletin headlines correcting police, money sum, relative-who, and collective traps.",
        projStages = listOf("Fix 'The police has warned...' → 'The police have warned...'", "Fix 'Twenty thousand naira were spent' → 'was spent'.", "Fix 'One of the girls who sits near' → 'who sit near'."),
        projRubric = listOf("Recognizes police always plural.", "Treats money sums as single lump.", "Matches 'who' antecedent 'girls' cleanly."),
        projModel = "1) 'The police have recovered the bus.' 2) 'Five million naira was allocated to laboratories.' 3) 'She is one of the debaters who speak fluently.' 4) 'Many a promising athlete loses focus early.'",
        cheatOverview = "Ignore 'as well as'; Match nearer after 'or/nor'; Each/Many a = Sing; Police/The poor/A number = Plural.",
        cheatLegend = listOf("One THE = 1 person", "Two THEs = 2 people", "The number = IS", "A number = ARE"),
        cheatTraps = listOf("Saying 'The police is'", "Matching 'as well as' plurals", "Forgetting 'Many a + sing'"),
        cheatMemory = "A Number = MANY (ARE); THE Number = ONE Figure (IS)!",
      ),
      "eng_07_tags_punctuation" to spec(
        prereq = listOf("eng_06_concord (verb agreement)", "Auxiliary verbs (do/does/did/have/will/can)"),
        dep = "Polarity-flip question tags and semicolon/apostrophe accuracy guard against mechanical punctuation losses across Essays & Lexis.",
        vocab = listOf(
          VocabularyEntry("Question Tag Polarity Flip", "Positive main statement → Negative tag ('...isn't it?'); Negative statement → Positive tag ('...is it?').", "Seesaw polarity check inviting agreement.", "Bare negative adverbs (hardly, seldom, scarcely, rarely, barely, little, few) make main clause NEGATIVE → POSITIVE tag!"),
          VocabularyEntry("Special Tag Imperatives & 'I am'", "'I am...' → 'aren't I?'; 'Let's...' → 'shall we?'; Commands/Let us (permission) → 'will you?'; Everyone/Nobody → 'they'!", "Five non-negotiable tag anomalies tested yearly.", "Positive 'used to' → 'didn't they?'; 'ought to' → 'oughtn't they?'!"),
          VocabularyEntry("Apostrophe Rules", "Singular ('Ada's book', 'James's car'), Plural ending in s ('students' hall'—after s!), Irregular plural ('children's toys').", "Possession vs Contraction (It's = It is; Its = Possessive!).", "ZERO apostrophe on 'its', 'yours', 'hers', 'ours', 'theirs'!"),
          VocabularyEntry("Semicolon (;) vs Colon (:)", "Semicolon joins two independent clauses tightly; Colon introduces list/explanation AFTER a complete clause.", "Semicolon = Period-light; Colon = Drumroll reveal!", "NEVER drop a colon straight after a verb ('My subjects are: Math...' is WRONG!)."),
        ),
        mech1 = "Why does 'She HARDLY visits Abuja, ___?' finish with POSITIVE 'DOES she?' instead of 'doesn't she?'? Words like hardly, scarcely, rarely, seldom, barely, few, little, never, nothing, nobody already carry negative charge inside the main sentence—so flipping twice ('doesn't she?') would turn double-negative!",
        mech2 = "Notice how 'Let's go home, SHALL WE?' (friendly suggestion including the speaker!) contrasts cleanly with 'Let us borrow your ruler, WILL YOU?' (polite request directed strictly at listener!)!",
        intel1 = "JAMB tests hidden negative adverbs ('seldom/hardly' → positive tag!), 'There is/are' ('...isn't there?'), 'I am' ('aren't I?'), and 'Everything/Everyone' pronoun shift ('it' vs 'they'!).",
        intel2 = "WAEC Essays deduct Mechanical Accuracy marks rapidly for missing question marks on polite requests, writing 'it's' for possessive 'its', and breaking colons after linking verbs.",
        recap1 = "Hardly/Scarcely/Seldom/Little/Few → POSITIVE tag! ('does she? / can he?')",
        recap2 = "Everyone/Nobody → 'they' in tag; Everything/Nothing → 'it' in tag!",
        sec3Title = "3. Pronoun Shifts in Tags, Hyphens & Mechanical Punctuation",
        sec3Body = "Match tag subjects carefully: 'Nobody called, DID THEY?' (Nobody = negative + plural-reference pronoun 'they'); 'Nothing broke, DID IT?' (Nothing = negative + singular 'it'); 'This/That' → 'it'; 'These/Those' → 'they'! Hyphenate compound adjectives placed BEFORE a noun ('a TEN-YEAR-OLD girl'), NEVER after ('the girl is ten years old').",
        sec3Formula = "\\text{Pos Main} \\rightarrow \\text{Neg Tag}   |   \\text{Neg (Hardly/Nobody) Main} \\rightarrow \\text{Pos Tag}   |   \\text{It's} = \\text{It is}",
        sec3Tip = "No apostrophe EVER goes into '1990s' decades or possessive 'yours sincerely / its leg'!",
        sec3Mech = "Apostrophes strictly mark missing letters (can't, it's) or noun ownership (girl's, girls'), NEVER verb/pronoun plurals.",
        sec3Intel = "WAEC Mechanical Accuracy subtracts ½ mark per error—apostrophe mastery protects 5+ free marks effortlessly.",
        sec3Recap = "Your's / It's (belonging) = Zero tolerance error! Compound modifiers before nouns need hyphens.",
        sec4Title = "4. WAEC Letter Signatures & Punctuating Market Notices",
        sec4Body = "Writing 'Your's faithfully' on a WAEC formal letter instantly triggers a mechanical-accuracy red pen! Remembering 'Yours faithfully' (no apostrophe) and placing apostrophes AFTER plural 's' in 'Girls' Hostel' keeps official notices crisp and credible.",
        sec4Tip = "Formal closing with 'Dear Sir/Madam' → 'Yours faithfully' (small 'f', zero apostrophe!).",
        sec5Title = "5. Auxiliary-Verb Isolation & 'No' Agreement Check",
        sec5Body = "Note how Nigerian English replies to negative tag questions ('You didn't go, did you?' — 'Yes, I didn't'!) collide with Standard English: if the truth is negative ('didn't go'), Standard English MUST reply 'NO, I didn't'; if positive ('went'), reply 'YES, I did!' regardless of how the question was phrased!",
        sec5Tip = "Agreement relies on TRUE FACT, not matching the speaker's question polarity: Went = YES I did; Didn't go = NO I didn't!",
        misc1 = MisconceptionAnalysis("'She seldom smiles, doesn't she?' is right because main verb 'smiles' has no 'not'.", "Positive-looking verb.", "'Seldom', 'hardly', 'scarcely', 'barely', 'rarely', 'few', 'little' make the statement NEGATIVE—forcing POSITIVE tag 'DOES she?'!", "Scan every main clause for semi-negative adverbs before choosing tag polarity."),
        misc2 = MisconceptionAnalysis("Possessive 'its' needs an apostrophe like 'Ada's' ('The dog wagged it's tail').", "Ownership takes 's.", "Possessive pronouns (his, hers, its, ours, yours, theirs) NEVER take an apostrophe! 'It's' strictly means 'it is / it has'.", "Test replacement with 'it is'—if broken, drop the apostrophe!"),
        guidedPrompt = "Supply exact question tags AND fix punctuation: (a) 'Everyone rarely complains about food, ___?' (b) 'Let's revise together, ___?' (c) 'The student's union rejected it's own budget, however they reconsidered.'",
        guidedHints = listOf(
          "Hint 1: (a) 'rarely' = negative; 'Everyone' takes pronoun 'they'; present simple plural = 'do they?'!",
          "Hint 2: (b) 'Let's' (suggestion) → 'shall we?'.",
          "Hint 3: (c) Plural students' union → Students' Union; possessive 'its' drops apostrophe; '; however,' needs semicolon!",
        ),
        guidedApproach = "Scan semi-negatives + Everyone→they → apply Let's rule → fix apostrophe & semicolon.",
        guidedSolution = "(a) 'do they?' ('rarely' is negative; 'everyone' maps to 'they'). (b) 'shall we?'. (c) 'The Students' Union rejected its own budget; however, they reconsidered.'",
        projTitle = "WAEC Mechanical-Accuracy & Tag Proofing Lab",
        projScenario = "Audit a formal Student Union petition fixing 4 punctuation/tag slips before submission.",
        projStages = listOf("Fix 'Your's sincerely' and 'it's roof'.", "Convert ', however,' comma splice into '; however,'.", "Verify 'I am eligible, aren't I?' and 'No one arrived early, did they?'."),
        projRubric = listOf("Eliminates apostrophe on Yours & possessive Its.", "Fixes semicolon splice.", "Gets 'aren't I' & 'did they' 100% accurate."),
        projModel = "'I am eligible, aren't I? No one arrived early, did they? The Girls' Dormitory lost its roof; however, repairs start tomorrow. Yours faithfully,'",
