        sec5Tip = "Circle 'OPPOSITE' or 'NEAREST' mentally on every single question!",
        misc1 = MisconceptionAnalysis("'Invaluable' and 'Inflammable' mean 'not valuable' and 'not able to burn'.", "'In-' means 'not' in invisible.", "'Invaluable' means TOO valuable to price (PRICELESS); 'Inflammable' means easily set IN flames (FLAMMABLE — 'non-flammable' is the opposite!).", "Watch 'Invaluable = Priceless' & 'Inflammable = Easily burns'!"),
        misc2 = MisconceptionAnalysis("'Disinterested' means bored and unconcerned.", "Confused with 'uninterested'.", "A 'disinterested referee' has ZERO personal stake—impartial & unbiased! 'Uninterested' means bored.", "Judge = Disinterested (Fair); Bored viewer = Uninterested."),
        guidedPrompt = "Pick Nearest vs Opposite carefully: (a) 'Far from being SPARING with funds, the philanthropist was...' (Opposite: stingy / lavish / cautious / prudent). (b) 'We need a DISINTERESTED mediator for the dispute.' (Nearest: bored / biased / impartial / tired). Explain both.",
