      "eng_09_idioms_phrasal_verbs" to spec(
        prereq = listOf("eng_08_synonyms_antonyms"),
        dep = "Non-literal idioms and phrasal-verb particle shifts anchor Precision Prepositions and Reading Inference.",
        vocab = listOf(
          VocabularyEntry("Literal vs Idiomatic", "Fixed expression whose meaning differs completely from individual words ('kick the bucket' = die).", "Word package holding secret code meaning.", "NEVER pick the option repeating physical words from the idiom!"),
          VocabularyEntry("Phrasal Verb", "Verb + particle/preposition creating brand-new meaning ('put off' ≠ put + off).", "Tiny tail ('up/out/off/over') transforming the verb.", "'Put off' = postpone; 'Call off' = cancel; 'Put out' = extinguish!"),
          VocabularyEntry("Separable vs Inseparable", "Pronouns MUST sit BETWEEN separable verb+particle ('turn IT off', NEVER 'turn off it'!).", "Pronoun squeeze inside phrasal verbs.", "Inseparable verbs keep object after particle ('look after the baby', NOT 'look the baby after')!"),
          VocabularyEntry("Fixed Nigerian Transfers", "Watch 'flash/drop/stay' idioms vs Standard British/International idioms ('take with a pinch of salt', 'sit on the fence').", "Standard exam idioms vs literal street translations.", "'Put on/turn off the light'—NOT 'on the light' or 'off the light'!"),
        ),
        mech1 = "Why is the LITERAL distractor almost always the WRONG choice on JAMB/WAEC idiom questions? Idioms exist specifically to paint figurative meaning—so 'bought a white elephant' NEVER means buying an albino zoo animal; it means funding an expensive useless prestige project!",
        mech2 = "Changing ONE tiny particle behind 'LOOK' flips meaning across 6 worlds: Look FOR (search), Look AFTER (care for), Look INTO (investigate), Look UP TO (admire), Look DOWN ON (despise), Look FORWARD TO (eagerly expect + -ing)!",
        intel1 = "JAMB tests 'call off vs put off', 'take after' (resemble!), 'turn down' (reject!), 'give in vs give up', and pronoun separation ('put IT on').",
        intel2 = "WAEC Paper 1 tests classic 10-question idiom/interpretation blocks ('hit the nail on the head', 'let the cat out of the bag', 'throw in the towel', 'burn the midnight oil', 'sit on the fence').",
        recap1 = "Reject any option reusing literal animal/object words from the idiom!",
        recap2 = "Put pronoun objects IN THE MIDDLE of separable phrasals: 'call IT off', NEVER 'call off it'!",
        sec3Title = "3. High-Yield Phrasal Verb Families & Literal-Trap Elimination",
        sec3Body = "Master high-frequency families cleanly: PUT (put off=postpone, put out=extinguish, put up with=tolerate, put across=explain); TURN (turn up=arrive, turn down=reject, turn out=produce/prove); BREAK (break down=fail/cry, break into=burgle, break out=escape/erupt); TAKE (take after=resemble, take in=deceive/comprehend, take over=assume control). Notice 'cope WITH' (NEVER 'cope up with'!).",
        sec3Formula = "\\text{Separable Phrasal + Pronoun} \\;\\longrightarrow\\; \\text{Verb + [it / them / him] + Particle}",
        sec3Tip = "Never write 'cope UP with'—Standard English is strictly 'cope WITH'!",
        sec3Mech = "Adding extra 'up' to 'cope with' is a classic redundant particle error penalized across WAEC & JAMB.",
        sec3Intel = "NECO/JAMB frequently pair 'put up with' (tolerate) against 'put off' (postpone) in identical contexts.",
        sec3Recap = "Eliminate literal traps → test particle sense → keep 'cope with' clean.",
        sec4Title = "4. Replacing Campus Redundancies in Formal Reports",
        sec4Body = "Everyday expressions like 'voice out', 'discuss about', 'round up' (when ending a lecture—actually 'round OFF'!), and 'cope up with' weaken formal interviews. Writing 'voice their grievances', 'discuss the issue', 'round off the speech', and 'cope with stress' wins full academic marks.",
        sec4Tip = "'Round UP' gathers cattle/suspects; 'Round OFF' concludes a speech or meeting cleanly!",
        sec5Title = "5. Pronoun-Placement & Particle-Opposite Audit",
        sec5Body = "Always verify 'turn down' (reject) vs 'turn up' (appear/increase), 'take off' (depart/undress) vs 'take in' (absorb/deceive), and remember 'throw in the towel' (surrender) vs 'keep under one's hat' (keep strictly secret)!",
        sec5Tip = "Let the cat out of the bag = reveal a secret accidentally!",
        misc1 = MisconceptionAnalysis("Rounding UP a speech or lecture means bringing it to a close.", "Heard daily at assemblies.", "'Round UP' means gather together (police rounded up suspects / round up 3.8 to 4); ending a talk/session is 'round OFF'!", "Conclude = Round OFF; Gather = Round UP."),
        misc2 = MisconceptionAnalysis("Putting 'cope up with' or 'put off' and 'call off' together means the same thing.", "Both delay plans.", "'Put off' = Postpone to a later date; 'Call off' = Cancel completely; 'Cope with' = Manage (NEVER 'cope up with'!).", "Put off = Delay; Call off = Cancel."),
        guidedPrompt = "Interpret each bold expression AND fix the grammatical glitch: (a) 'The strike was CALLED OFF after talks, so students can PUT ON their lab coats and ROUND UP the term cleanly.' (b) 'We must cope up with traffic.'",
        guidedHints = listOf(
          "Hint 1: 'Called off' = completely cancelled (NOT merely delayed!).",
