        guidedApproach = "Decode phrasal sense → correct 'round up' → trim 'cope up with'.",
        guidedSolution = "'Called off' = cancelled completely. Replace 'round up' with 'round off' (conclude the term) and replace 'cope up with' with 'cope with'.",
        projTitle = "Campus Journalism Idiom & Phrasal-Verb Clean-Up Guide",
        projScenario = "Edit 4 campus newsletter sentences eliminating 'round up (speech)', 'cope up with', 'white elephant literal', and 'turn off it'.",
        projStages = listOf("Explain 'white elephant' figuratively.", "Move pronoun inside 'turn it off'.", "Replace 'round up' & 'cope up with' cleanly."),
        projRubric = listOf("Decodes white elephant as costly useless venture.", "Applies separable pronoun rule.", "Fixes Nigerian redundant particle slips."),
        projModel = "'The unfinished stadium became a white elephant (costly, useless project). Before locking the hall, turn IT off and round OFF the ceremony calmly so new students cope WITH campus schedules.'",
        cheatOverview = "Reject literal idiom traps; Pronoun inside separable verb+particle; Call off=Cancel; Put off=Delay.",
