      "eng_10_prepositions_confusables" to spec(
        prereq = listOf("eng_09_idioms_phrasal_verbs"),
        dep = "Fixed prepositions, zero-preposition transitive verbs, and confusable word pairs guard directly against WAEC/JAMB objective traps.",
        vocab = listOf(
          VocabularyEntry("Zero-Preposition Transitive Verbs", "Discuss, Comprise, Demand, Emphasize, Advocate, Resemble, Seek, Order, Approach — take NO preposition after them!", "Action jumps straight onto object—no bridge word allowed!", "'We discussed the plan' (NOT 'discussed about'!); 'Comprises 5 units' (NOT 'comprises of'!)."),
          VocabularyEntry("Fixed Collocations", "Congratulate ON; Accuse OF; Charge WITH; Acquit OF; Abstain FROM; Rely ON; Prefer X TO Y; Comply WITH.", "Exact locked pairs memorized like chemistry formulas.", "'Superior TO', 'Senior TO', 'Inferior TO'—NEVER 'than' or 'for'!"),
          VocabularyEntry("Confusable Pair Examples", "Stationery(paper)/Stationary(still); Compliment(praise)/Complement(complete); Principal/Principle; Advice/Advise; Practice/Practise.", "Spelling-sound twins differing sharply by C vs S or E vs A!", "C = Noun (Advice, Practice, Licence); S = Verb (Advise, Practise, LicenSe in BrE)!"),
          VocabularyEntry("At / On / In; In vs Into", "AT exact point/clock; ON surface/day-date; IN enclosed city/month-year; INTO signals inward motion!", "Precision target (At) → Surface (On) → Container (In).", "'Jumped INTO the pool' (motion) vs 'Swam IN the pool' (inside)!"),
        ),
        mech1 = "Why is 'She comprises of four modules' wrong while 'She consists of four modules' is completely right? 'Comprise' ALREADY packs the meaning 'consist of' inside itself—adding 'of' repeats 'of' twice! Similarly, 'discuss' = 'talk about' (adding 'about' doubles it!), and 'return' = 'go back' (never write 'return back'!).",
        mech2 = "In British/WAEC spelling, split C (Noun) from S (Verb) instantly using ICE vs IS: 'advICE' is a noun ('Give me good advice'), while 'advISE' is a verb ('Please advise me')—matching 'practICE / practISE' and 'licenCE / licenSE' cleanly!",
        intel1 = "JAMB tests 'congratulate ON' (not 'for'), 'die OF' (disease: malaria/hunger) vs 'die FROM' (external cause: wound/neglect/poison), 'comprise (0 of)', and 'stationery vs stationary'.",
        intel2 = "WAEC Paper 1 tests Latin comparatives taking 'TO' ('senior TO', 'junior TO', 'prefer X TO Y'—never 'than'!), plus 'hangar (plane)' vs 'hanger (coat)', 'imminent' vs 'eminent'.",
        recap1 = "Discuss, Comprise, Emphasize, Resemble, Order, Demand → ZERO preposition!",
        recap2 = "Prefer/Senior/Junior/Inferior/Superior → take TO (never 'than'!); Noun = -CE, Verb = -SE.",
        sec3Title = "3. Noun/Verb C-vs-S Pairs, Die-Of/From & Motion Prepositions",
        sec3Body = "High-yield WAEC/JAMB pairs: (1) Stationary (unmoving parked car) vs Stationery (pens/paper—E for Envelope!); (2) Principal (head / main — 'pal') vs Principle (rule); (3) Compliment (nice praise — 'I like praise') vs Complement (completes a set — 'E for complete'); (4) Lose (misplace) vs Loose (baggy); (5) Continual (repeatedly pausing) vs Continuous (unbroken); (6) Among (>2 people) vs Between (2 people).",
        sec3Formula = "\\text{Noun: } -ce\\; (\\text{advice, practice})   |   \\text{Verb: } -se\\; (\\text{advise, practise})   |   \\text{Comprise (} \\emptyset \\text{ of)}",
        sec3Tip = "'Die OF' goes with internal illness/hunger ('died of cholera'); 'Die FROM' goes with injury/overwork/external cause ('died from wounds')!",
        sec3Mech = "Direct preposition pairing distinguishes internal biological pathology (of) from external physical trauma (from).",
        sec3Intel = "NECO/JAMB frequently put both 'of' and 'from' in options A and B!",
        sec3Recap = "E for Envelope = Stationery; 'Pal' = Head Principal; C = Noun, S = Verb.",
        sec4Title = "4. Clearing Common Nigerian Administrative Preposition Slips",
        sec4Body = "Office memos frequently print 'congratulate you for', 'request for', 'advocate for', or 'comprising of'. Switching strictly to 'congratulate you ON', 'request leave' (verb takes zero 'for'!), 'advocate reform', and 'comprising five units' raises business writing cleanly to global standard.",
        sec4Tip = "'A request FOR' (noun takes 'for'); 'We request' (verb takes NO 'for'!)!",
        sec5Title = "5. Transitive-Verb Redundancy & Spelling Twin Check",
        sec5Body = "Spot silent redundancy traps instantly: 'return back', 'repeat again', 'reverse back', 'can be able to', 'discuss about', 'comprise of', 'more better' — every single one doubles meaning already inside the root word!",
        sec5Tip = "Remember 'Arrive AT' a small building/airport vs 'Arrive IN' a big city or country!",
        misc1 = MisconceptionAnalysis("'We discussed about the problem' and 'The exam comprises of 50 questions' are formal English.", "Uses familiar patterns from 'talk about' & 'consists of'.", "'Discuss' and 'Comprise' already contain 'about' and 'of' inside their meanings—take direct objects cleanly: 'discussed the problem', 'comprises 50 questions'!", "Zero preposition after Discuss, Comprise, Demand, Emphasize, Order."),
        misc2 = MisconceptionAnalysis("'I prefer rice than beans' and 'She is senior than me' are normal comparative sentences.", "Normal comparatives use 'than'.", "Latin-root comparatives (superior, inferior, senior, junior, prior, prefer) take preposition 'TO', NEVER 'than'!", "Prefer / Senior / Inferior + TO."),
        guidedPrompt = "Correct ALL errors: 'I congratulate you for your success; please advise me on how to choose between stationary and stationery, as I prefer tea than coffee and the team comprises of six youths senior than me.'",
        guidedHints = listOf(
