        sec5Title = "5. Orthographic Illusion Trap Check",
        sec5Body = "If three options share 'oo' (e.g., 'blood, food, mood, pool') and you're asked to match 'cut' /ʌ/, NEVER hesitate picking 'blood' /blʌd/! Examiners specifically plant identical-looking letters to trap visual guessers.",
        sec5Tip = "Look at SOUNDS only, cross out spelling letters mentally!",
